var ALL_ELEMENTS={
Al:{symbol:"Al",name:"Aluminium",z:13,color:"#4a9ee8",body:"<strong>Aluminium</strong> is the most abundant metal in Earth's crust. Recycling uses only 5% of primary production energy.",fun:"\ud83d\udca1 Napoleon III is said to have given his most honoured guests aluminium plates and cutlery!",real:"Nobody digs aluminium metal - bauxite ore is refined, then split apart with enormous amounts of electricity.",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Fe:{symbol:"Fe",name:"Iron",z:26,color:"#a0785a",body:"<strong>Iron</strong> is the backbone of civilisation. Steel forms the structural core of almost every large machine and building.",fun:"\ud83d\udca1 Earth's core is mostly iron - and its churning liquid outer part creates our magnetic field!",real:"Iron is the friendly exception: some ores are over 60% metal, scooped from open pits by house-sized machines.",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Cu:{symbol:"Cu",name:"Copper",z:29,color:"#d4884a",body:"<strong>Copper</strong> is the world's most important electrical conductor. Chile produces around a quarter of global supply.",fun:"\ud83d\udca1 Copper is naturally antimicrobial - bacteria die within hours on copper surfaces!",real:"Copper ore is typically under 1% metal - the other 99% of the rock becomes mine waste.",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Ni:{symbol:"Ni",name:"Nickel",z:28,color:"#9ab8a0",body:"<strong>Nickel</strong> adds strength to steel and is a key battery cathode material. Indonesia alone now produces over half the world's supply.",fun:"\ud83d\udca1 The US 5-cent coin is actually 75% copper - only 25% nickel!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Zn:{symbol:"Zn",name:"Zinc",z:30,color:"#a8b8c8",body:"<strong>Zinc</strong> protects steel from corrosion through galvanising. Also essential for human health.",fun:"\ud83d\udca1 Ships carry sacrificial zinc blocks bolted to the hull - the zinc corrodes away so the steel doesn't!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Sn:{symbol:"Sn",name:"Tin",z:50,color:"#c8c0b0",body:"<strong>Tin</strong> is the main component of lead-free solder. Offshore tin dredging in Indonesia has devastated coral reefs.",fun:"\ud83d\udca1 Tin cry - the crackling when you bend tin - is caused by crystal twinning!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Au:{symbol:"Au",name:"Gold",z:79,color:"#e8b84b",body:"<strong>Gold</strong> coats connectors because it never corrodes. The 1.2 billion smartphones sold each year contain roughly 40 tonnes of gold.",fun:"\ud83d\udca1 Your phone drawer is richer in gold per tonne than most gold mines!",real:"Real gold ore holds just a few grams per tonne: mines crush several tonnes of rock for a wedding ring's worth.",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Ag:{symbol:"Ag",name:"Silver",z:47,color:"#c0c8d8",body:"<strong>Silver</strong> has the highest electrical conductivity of any element. Essential for solar cells and circuit traces.",fun:"\ud83d\udca1 Silver's symbol Ag comes from the Latin 'argentum' - and Argentina is named after it!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Li:{symbol:"Li",name:"Lithium",z:3,color:"#e85454",body:"<strong>Lithium</strong> is the lightest metal. Around two-fifths of the world's known resources sit in the lithium triangle of Chile, Argentina, and Bolivia.",fun:"\ud83d\udca1 Lithium is so light it floats on water - and when it burns, its flame is a brilliant crimson red!",real:"Much lithium is not dug at all: it is pumped up as salty brine and dried in giant evaporation ponds.",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Co:{symbol:"Co",name:"Cobalt",z:27,color:"#5a7ec8",body:"<strong>Cobalt</strong> stabilises battery cathodes. Over 70% comes from the DR Congo - and in the small hand-dug mines that supply part of it, child labour has been documented.",fun:"\ud83d\udca1 Named after Kobold (goblin) - miners blamed goblins for the toxic fumes!",real:"No blue gems - cobalt is mostly a byproduct of copper and nickel mining, refined in industrial plants.",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Mn:{symbol:"Mn",name:"Manganese",z:25,color:"#c87ae8",body:"<strong>Manganese</strong> strengthens steel and is vital in NMC battery cathodes. South Africa holds around 70% of the world's known manganese resources.",fun:"\ud83d\udca1 Neanderthals collected manganese dioxide 50,000 years ago - possibly to help light their fires!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
P:{symbol:"P",name:"Phosphorus",z:15,color:"#e8d454",body:"<strong>Phosphorus</strong> is critical for LFP batteries. Also essential for all life - DNA, bones, and cell membranes.",fun:"\ud83d\udca1 Phosphorus was discovered in 1669 by boiling urine - it glows in the dark!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
C:{symbol:"C",name:"Graphite",z:6,color:"#555555",body:"<strong>Graphite</strong> (carbon) forms the anode in almost all lithium-ion batteries. China mines more than three-quarters of the world's supply.",fun:"\ud83d\udca1 Graphite and diamond are both pure carbon - just arranged differently!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Nd:{symbol:"Nd",name:"Neodymium",z:60,color:"#4ae87a",body:"<strong>Neodymium</strong> creates the strongest permanent magnets. NdFeB magnets power EV motors, wind turbines, and speakers.",fun:"\ud83d\udca1 A coin-sized Nd magnet can lift several kilograms!",real:"Rare earths are not rare - the hard part is separating more than a dozen nearly identical metals from one another.",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Dy:{symbol:"Dy",name:"Dysprosium",z:66,color:"#6ae8c8",body:"<strong>Dysprosium</strong> is added to neodymium magnets so they work at high temperatures. One of the hardest rare earths to source.",fun:"\ud83d\udca1 Dysprosium means 'hard to get' in Greek - and it still is!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Pr:{symbol:"Pr",name:"Praseodymium",z:59,color:"#88e878",body:"<strong>Praseodymium</strong> is alloyed with neodymium for high-performance magnets. Also makes a bright yellow pigment for ceramics and glazes.",fun:"\ud83d\udca1 Praseodymium means 'green twin' - its salts are a fresh leaf-green!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Er:{symbol:"Er",name:"Erbium",z:68,color:"#e87aaa",body:"<strong>Erbium</strong> amplifies light signals in fibre optic cables. Without it, signals fade after ~100 km.",fun:"\ud83d\udca1 Erbium gives glass a beautiful pink colour!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Y:{symbol:"Y",name:"Yttrium",z:39,color:"#aade88",body:"<strong>Yttrium</strong> is used in LED phosphors, lasers, and superconductors. Named after Ytterby, Sweden.",fun:"\ud83d\udca1 Four elements are named after Ytterby - more than any other place on Earth!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Si:{symbol:"Si",name:"Silicon",z:14,color:"#7888c8",body:"<strong>Silicon</strong> is the foundation of almost all microchips and solar cells. Ultra-pure silicon is one of the purest materials ever made.",fun:"\ud83d\udca1 Silicon Valley is named after this element - sand is mostly silicon dioxide!",real:"Silicon is not mined as chips: quartz is smelted, then purified to 99.9999999% for electronics.",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Ga:{symbol:"Ga",name:"Gallium",z:31,color:"#a87ae8",body:"<strong>Gallium</strong> semiconductors handle 5G signals. China produces almost all of the world's new gallium and restricted its export in 2023.",fun:"\ud83d\udca1 Gallium melts at 29.8\u00b0C in your hand, but only boils above 2,200\u00b0C!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Ge:{symbol:"Ge",name:"Germanium",z:32,color:"#88ccaa",body:"<strong>Germanium</strong> is used in fibre optics, infrared lenses, and transistors. Predicted by Mendeleev before discovery.",fun:"\ud83d\udca1 Mendeleev called it 'eka-silicon' - his predictions were almost exactly right!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
In:{symbol:"In",name:"Indium",z:49,color:"#e85454",body:"<strong>Indium</strong> forms transparent conductive coatings for touchscreens and solar cells. Almost all of it is a by-product of zinc refining.",fun:"\ud83d\udca1 Indium gives a high-pitched 'cry' when you bend it!",real:"Indium is never dug up on its own - it is recovered in tiny traces during zinc smelting.",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Ta:{symbol:"Ta",name:"Tantalum",z:73,color:"#c87878",body:"<strong>Tantalum</strong> creates tiny, powerful capacitors. Its ore coltan has fuelled conflict in the DR Congo.",fun:"\ud83d\udca1 Named after King Tantalus - the metal sits in acid without dissolving!",real:"Tantalum comes from coltan ore - a large share dug by hand in small artisanal mines in Central Africa.",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Pd:{symbol:"Pd",name:"Palladium",z:46,color:"#d0c8b8",body:"<strong>Palladium</strong> cleans car exhaust in catalytic converters and is used in electronics. Russia and South Africa produce about three-quarters of it.",fun:"\ud83d\udca1 Palladium can absorb 900 times its own volume of hydrogen!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Pt:{symbol:"Pt",name:"Platinum",z:78,color:"#b0b0d0",body:"<strong>Platinum</strong> catalyses fuel cells and refining. Mined at only about one-twentieth the rate of gold. South Africa holds about 80% of known platinum-group reserves.",fun:"\ud83d\udca1 All the platinum ever mined would fit in a cube less than 10 metres across!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Ir:{symbol:"Ir",name:"Iridium",z:77,color:"#b0c8e8",body:"<strong>Iridium</strong> is the most corrosion-resistant metal. Used in satellite thrusters and spark plugs.",fun:"\ud83d\udca1 An iridium-rich layer in rock marks the asteroid that killed the dinosaurs!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
W:{symbol:"W",name:"Tungsten",z:74,color:"#8899bb",body:"<strong>Tungsten</strong> has the highest melting point of any metal (3,422\u00b0C). Used in drill bits and X-ray shielding.",fun:"\ud83d\udca1 Tungsten's symbol W comes from 'Wolfram' - German for 'wolf foam'!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Ti:{symbol:"Ti",name:"Titanium",z:22,color:"#88aad8",body:"<strong>Titanium</strong> is as strong as steel but 45% lighter. Used in aerospace, medical implants, and satellites.",fun:"\ud83d\udca1 Titanium is named after the Titans of Greek mythology!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Nb:{symbol:"Nb",name:"Niobium",z:41,color:"#a8a0d8",body:"<strong>Niobium</strong> is a superconductor for MRI magnets. Brazil controls 90% of global production.",fun:"\ud83d\udca1 Named after Niobe, daughter of Tantalus - because niobium is so like its sibling element, tantalum!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Mo:{symbol:"Mo",name:"Molybdenum",z:42,color:"#b8a8a0",body:"<strong>Molybdenum</strong> strengthens steel for turbine shafts and pipelines. Withstands extreme heat.",fun:"\ud83d\udca1 Molybdenum melts at 2,623\u00b0C - so it is used for furnace and rocket parts!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Cr:{symbol:"Cr",name:"Chromium",z:24,color:"#c0d0e0",body:"<strong>Chromium</strong> makes stainless steel stainless with an invisible oxide layer. Also used in chrome plating.",fun:"\ud83d\udca1 Chromium means 'colour' - its compounds span every colour of the rainbow!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Pb:{symbol:"Pb",name:"Lead",z:82,color:"#888888",body:"<strong>Lead</strong> is dense and soft: it shields against X-rays in medical imaging, and most of it goes into batteries. It is poisonous, especially to children - which is why it was taken out of petrol and paint.",fun:"\ud83d\udca1 'Plumbing' comes from 'plumbum' (lead) - Romans used lead water pipes, even though the Roman engineer Vitruvius warned that lead was unhealthy!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Cd:{symbol:"Cd",name:"Cadmium",z:48,color:"#d8a878",body:"<strong>Cadmium</strong> telluride makes thin-film solar panels, the main rival to silicon. The cadmium is toxic, but it is sealed safely between sheets of glass.",fun:"\ud83d\udca1 Making a CdTe panel releases far less carbon dioxide than making a silicon one!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Te:{symbol:"Te",name:"Tellurium",z:52,color:"#d8c0a0",body:"<strong>Tellurium</strong> is one of the rarest elements in Earth's crust - about as scarce as gold. Combined with cadmium, it makes efficient solar cells.",fun:"\ud83d\udca1 Tellurium gives garlic breath to anyone who handles it!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
He:{symbol:"He",name:"Helium",z:2,color:"#f0d0e0",body:"<strong>Helium</strong> cools superconducting magnets to near absolute zero. Non-renewable - once released, it escapes to space.",fun:"\ud83d\udca1 Helium was discovered on the Sun before it was found on Earth!",real:"Helium really is found underground - but as a gas trapped in natural-gas fields, not a crystal.",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Gd:{symbol:"Gd",name:"Gadolinium",z:64,color:"#90d8b0",body:"<strong>Gadolinium</strong> is a contrast agent for MRI scans. Also absorbs neutrons better than any other natural element, so it is used in nuclear reactors.",fun:"\ud83d\udca1 Gadolinium turns ferromagnetic below about 20\u00b0C - warm it in your hand and it stops sticking to a magnet!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
F:{symbol:"F",name:"Fluorine",z:9,color:"#a0e8a0",body:"<strong>Fluorine</strong> compounds coat fibre optic cables and etch semiconductors. The most reactive element.",fun:"\ud83d\udca1 Early attempts to isolate fluorine killed or injured several chemists!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Zr:{symbol:"Zr",name:"Zirconium",z:40,color:"#c8d0c0",body:"<strong>Zirconium</strong> makes precision fibre optic connectors and nuclear fuel cladding. Extremely corrosion-resistant.",fun:"\ud83d\udca1 Cubic zirconia (fake diamond) is made from zirconium oxide!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Br:{symbol:"Br",name:"Bromine",z:35,color:"#c86040",body:"<strong>Bromine</strong> flame retardants in circuit boards prevent fires. One of only two liquid elements at room temperature.",fun:"\u{1f4a1} Bromine means 'stench' in Greek - it smells terrible!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
// ─── Remaining elements (Z=1–118, filling gaps in the periodic table) ───
H:{symbol:"H",name:"Hydrogen",z:1,color:"#e8e8f0",body:"<strong>Hydrogen</strong> is the most abundant element in the universe, making up about three-quarters of all normal matter by mass. It powers the Sun through nuclear fusion and is a promising clean fuel.",fun:"\u{1f4a1} A single glass of water contains more hydrogen atoms than there are stars in the observable universe!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
N:{symbol:"N",name:"Nitrogen",z:7,color:"#5a8ae8",body:"<strong>Nitrogen</strong> makes up 78% of Earth's atmosphere. Essential for fertilisers, explosives, and the amino acids in all living things.",fun:"\u{1f4a1} Liquid nitrogen is so cold (\u2212196\u00b0C) it can freeze a banana hard enough to hammer a nail!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
O:{symbol:"O",name:"Oxygen",z:8,color:"#e85050",body:"<strong>Oxygen</strong> is the third most abundant element in the universe. It makes up 21% of Earth's atmosphere and nearly half the mass of Earth's crust.",fun:"\u{1f4a1} Oxygen is paramagnetic - liquid oxygen is attracted to a magnet and has a pale blue colour!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Ne:{symbol:"Ne",name:"Neon",z:10,color:"#ff6060",body:"<strong>Neon</strong> produces the iconic red-orange glow in neon signs. It is the fifth most abundant element in the universe but rare on Earth.",fun:"\u{1f4a1} True neon signs only glow red-orange - other colours use different gases or phosphor coatings!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Na:{symbol:"Na",name:"Sodium",z:11,color:"#a8a0e8",body:"<strong>Sodium</strong> is essential for nerve function and fluid balance. Combined with chlorine, it forms common table salt. Molten sodium cools some nuclear reactors.",fun:"\u{1f4a1} Drop a lump of sodium in water and it fizzes, catches fire and can explode - real alkali metal fireworks!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Mg:{symbol:"Mg",name:"Magnesium",z:12,color:"#80d880",body:"<strong>Magnesium</strong> is the lightest structural metal. Used in aircraft, laptops, and car parts. Also vital for photosynthesis - it sits at the heart of chlorophyll.",fun:"\u{1f4a1} Magnesium burns so brightly it was used in early camera flashes and signal flares!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
S:{symbol:"S",name:"Sulphur",z:16,color:"#e8d830",body:"<strong>Sulphur</strong> is critical for sulphuric acid production, the world's most-used industrial chemical. Also essential in fertilisers and vulcanising rubber.",fun:"\u{1f4a1} The smell of rotten eggs comes from hydrogen sulphide - but pure solid sulphur is actually odourless!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Cl:{symbol:"Cl",name:"Chlorine",z:17,color:"#a8e850",body:"<strong>Chlorine</strong> disinfects drinking water worldwide, saving millions from waterborne diseases. Also used in PVC plastics and hundreds of pharmaceuticals.",fun:"\u{1f4a1} Chlorine was the first deadly gas used as a weapon in World War I - now it saves lives through sanitation!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Ar:{symbol:"Ar",name:"Argon",z:18,color:"#b0a0d0",body:"<strong>Argon</strong> makes up nearly 1% of Earth's atmosphere. This inert gas fills incandescent light bulbs, welding chambers, and double-glazed windows as insulation.",fun:"\u{1f4a1} Argon means 'lazy' in Greek - it was named for its refusal to react with anything!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
K:{symbol:"K",name:"Potassium",z:19,color:"#d0a0d0",body:"<strong>Potassium</strong> is essential for every living cell. It regulates heartbeat, nerve signals, and muscle contractions. Potassium fertilisers (potash) help grow much of the world's food.",fun:"\u{1f4a1} Bananas are very slightly radioactive due to potassium-40 - but far too little to do you any harm!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Ca:{symbol:"Ca",name:"Calcium",z:20,color:"#e8e0c0",body:"<strong>Calcium</strong> builds bones, teeth, and shells. It is the fifth most abundant element in Earth's crust. Portland cement, plaster, and marble are all calcium compounds.",fun:"\u{1f4a1} Your body contains about 1 kg of calcium - 99% of it is in your bones and teeth!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Sc:{symbol:"Sc",name:"Scandium",z:21,color:"#c0c0e8",body:"<strong>Scandium</strong> makes aluminium alloys much stronger, so parts can be thinner and lighter. Used in aerospace, sports equipment, and high-intensity stadium lighting.",fun:"\u{1f4a1} Soviet engineers pioneered super-strong scandium-aluminium alloys, planning to build them into MiG fighter jets!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
V:{symbol:"V",name:"Vanadium",z:23,color:"#7090c0",body:"<strong>Vanadium</strong> hardens steel for tools, springs, and engine parts. Vanadium redox flow batteries are a promising grid-scale energy storage technology.",fun:"\u{1f4a1} Named after Vanadis (Norse goddess of beauty) because of its many beautifully coloured compounds!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Se:{symbol:"Se",name:"Selenium",z:34,color:"#e89070",body:"<strong>Selenium</strong> made the first office photocopiers possible and is still used in solar cells and X-ray detectors. An essential trace nutrient for humans, but toxic in larger amounts.",fun:"\u{1f4a1} Brazil nuts are the richest food source of selenium - a single nut can cover your daily need!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Kr:{symbol:"Kr",name:"Krypton",z:36,color:"#b8d0e0",body:"<strong>Krypton</strong> is a rare noble gas used in high-performance insulating windows, photographic flash equipment, and certain fluorescent lamps.",fun:"\u{1f4a1} Superman's weakness is named after this real element - but real krypton is just a harmless noble gas!",risk:"low",riskLabel:"SUPPLY RISK: LOW"},
Rb:{symbol:"Rb",name:"Rubidium",z:37,color:"#c890a0",body:"<strong>Rubidium</strong> is used in atomic clocks, GPS satellites, and photoelectric cells. It melts at just 39\u00b0C and ignites spontaneously in air.",fun:"\u{1f4a1} GPS satellites carry rubidium atomic clocks - an error of a few billionths of a second would put your map off by metres!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Sr:{symbol:"Sr",name:"Strontium",z:38,color:"#50c878",body:"<strong>Strontium</strong> produces the brilliant red colour in fireworks and flares. Strontium-90 from nuclear fallout is dangerous because it mimics calcium in bones.",fun:"\u{1f4a1} Almost every red firework you see gets its colour from a strontium compound!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Tc:{symbol:"Tc",name:"Technetium",z:43,color:"#a0a0a0",body:"<strong>Technetium</strong> was the first artificially produced element. Its radioactive isotope Tc-99m is used in tens of millions of medical scans each year.",fun:"\u{1f4a1} Technetium means 'artificial' in Greek - it was discovered in 1937 in metal that had been bombarded in a cyclotron!",risk:"high",riskLabel:"REACTOR-MADE"},
Ru:{symbol:"Ru",name:"Ruthenium",z:44,color:"#a0b8c8",body:"<strong>Ruthenium</strong> hardens platinum and palladium alloys. Used in wear-resistant electrical contacts and emerging solar cell dyes.",fun:"\u{1f4a1} Ruthenium is named after Russia (Ruthenia in Latin) - one of several elements named after countries, alongside germanium, polonium and francium!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Rh:{symbol:"Rh",name:"Rhodium",z:45,color:"#d0d0e8",body:"<strong>Rhodium</strong> is one of the rarest and most expensive precious metals, used in catalytic converters, searchlight reflectors, and jewellery plating. Over 80% comes from South Africa.",fun:"\u{1f4a1} In 2021 rhodium hit nearly $30,000/oz - more than fifteen times the price of gold at the time!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Sb:{symbol:"Sb",name:"Antimony",z:51,color:"#a0a0b8",body:"<strong>Antimony</strong> is a key flame retardant in plastics and textiles. Its compound antimony trioxide is in many electronics housings to prevent fire.",fun:"\u{1f4a1} Antimony's symbol Sb comes from 'stibium', the Latin name for its black sulphide - which Roman writers describe as eye make-up!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
I:{symbol:"I",name:"Iodine",z:53,color:"#9860b0",body:"<strong>Iodine</strong> is essential for thyroid hormones that regulate metabolism. Iodised salt has prevented millions of cases of intellectual disability worldwide.",fun:"\u{1f4a1} Iodine sublimes into a beautiful violet gas - its name comes from the Greek word for 'violet'!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Xe:{symbol:"Xe",name:"Xenon",z:54,color:"#88a8d0",body:"<strong>Xenon</strong> powers ion thrusters for deep-space probes. Also used in anaesthesia, high-intensity headlamps, and bubble chambers for particle physics.",fun:"\u{1f4a1} Xenon means 'stranger' in Greek - it was a mysterious residue left after distilling liquid air!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Cs:{symbol:"Cs",name:"Caesium",z:55,color:"#e8d080",body:"<strong>Caesium</strong> atomic clocks define the SI second. Also used in oil drilling fluids and photoelectric cells. Melts at 28.5\u00b0C - the warmth of a hand would melt it, if it were safe to hold.",fun:"\u{1f4a1} The official second is defined as 9,192,631,770 oscillations of the microwaves given off by caesium-133 atoms!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Ba:{symbol:"Ba",name:"Barium",z:56,color:"#50b890",body:"<strong>Barium</strong> compounds produce green flames in fireworks. Barium meals (swallowed as a milkshake) make the stomach and gut show up on X-rays.",fun:"\u{1f4a1} Barium sulphate is so insoluble you can safely drink it for an X-ray - despite barium being toxic!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
La:{symbol:"La",name:"Lanthanum",z:57,color:"#70c8a0",body:"<strong>Lanthanum</strong> is used in camera and telescope lenses, hybrid car batteries, and petroleum refining catalysts. It gives its name to the entire lanthanide series.",fun:"\u{1f4a1} Lanthanum means 'to lie hidden' - it hid inside cerium oxide for over 35 years before being discovered!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Ce:{symbol:"Ce",name:"Cerium",z:58,color:"#e8e870",body:"<strong>Cerium</strong> is the most abundant rare earth element. Cerium oxide polishes glass and is used in catalytic converters and self-cleaning ovens.",fun:"\u{1f4a1} That sparkle when you strike a lighter? It's cerium in the flint creating those hot sparks!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Sm:{symbol:"Sm",name:"Samarium",z:62,color:"#d0a070",body:"<strong>Samarium</strong> makes powerful permanent magnets (SmCo) that work at temperatures where neodymium magnets fail. Also used in cancer treatment (Sm-153).",fun:"\u{1f4a1} Samarium is named after the mineral samarskite, which was named after a Russian mining official!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Eu:{symbol:"Eu",name:"Europium",z:63,color:"#e86090",body:"<strong>Europium</strong> gave colour televisions their bright red, and europium phosphors still glow in many lamps and white LEDs. Euro banknotes contain europium-based phosphors as an anti-counterfeiting measure.",fun:"\u{1f4a1} Before europium, the red in colour TVs was so weak that the other colours had to be dimmed to match!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Tb:{symbol:"Tb",name:"Terbium",z:65,color:"#60d890",body:"<strong>Terbium</strong> gives the green glow in fluorescent lamps and older screens. Today much of it goes into magnets that must stay strong when hot.",fun:"\u{1f4a1} Terbium is one of four elements named after Ytterby, a tiny Swedish village with an extraordinary quarry!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Ho:{symbol:"Ho",name:"Holmium",z:67,color:"#e870a0",body:"<strong>Holmium</strong> atoms are among the most strongly magnetic of any element. Used in powerful magnets, nuclear control rods, and medical lasers for surgery.",fun:"\u{1f4a1} Holmium is named after Stockholm (Holmia in Latin) - the home town of Per Teodor Cleve, one of its discoverers!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Tm:{symbol:"Tm",name:"Thulium",z:69,color:"#90d0c0",body:"<strong>Thulium</strong> is the rarest stable lanthanide. Some portable X-ray machines have used thulium-170 as their radiation source.",fun:"\u{1f4a1} Thulium is named after Thule, the ancient Greek name for a mythical northern land (Scandinavia)!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Yb:{symbol:"Yb",name:"Ytterbium",z:70,color:"#b0c890",body:"<strong>Ytterbium</strong> can improve stainless steel, and is used in stress gauges and fibre-optic signal amplifiers. The next-generation atomic clocks use ytterbium.",fun:"\u{1f4a1} Ytterbium atomic clocks may replace caesium as the world's time standard - they're 100\u00d7 more precise!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Lu:{symbol:"Lu",name:"Lutetium",z:71,color:"#a0b8a0",body:"<strong>Lutetium</strong> is the hardest and densest lanthanide. Used in PET scan detectors and as a catalyst in petroleum refining and organic chemistry.",fun:"\u{1f4a1} Lutetium is named after Lutetia, the Roman name for Paris - the city of light!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Hf:{symbol:"Hf",name:"Hafnium",z:72,color:"#c0c0d0",body:"<strong>Hafnium</strong> is outstanding for nuclear reactor control rods because it absorbs neutrons extremely well. Also used in advanced microprocessor chips.",fun:"\u{1f4a1} Hafnium was one of the last stable elements discovered (1923) - it hid inside zirconium minerals!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Re:{symbol:"Re",name:"Rhenium",z:75,color:"#a8b0c0",body:"<strong>Rhenium</strong> has the highest melting point of any metal except tungsten. It's essential in jet engine superalloys that must survive extreme temperatures.",fun:"\u{1f4a1} Rhenium was the last stable, naturally occurring element to be discovered - in 1925!",risk:"high",riskLabel:"SUPPLY RISK: CRITICAL"},
Os:{symbol:"Os",name:"Osmium",z:76,color:"#8090b0",body:"<strong>Osmium</strong> is the densest naturally occurring element. Used in fountain pen tips, electrical contacts, and its oxide has been used to reveal fingerprints.",fun:"\u{1f4a1} Osmium means 'smell' - its volatile oxide has a sharp, toxic, chlorine-like odour!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Tl:{symbol:"Tl",name:"Thallium",z:81,color:"#a0a088",body:"<strong>Thallium</strong> is used in superconductor research and sensitive infrared detectors. Extremely toxic - once notoriously used as a poison.",fun:"\u{1f4a1} Thallium was called 'the poisoner's poison' - it's colourless, odourless, and tasteless in solution!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Bi:{symbol:"Bi",name:"Bismuth",z:83,color:"#d890d0",body:"<strong>Bismuth</strong> is used in Pepto-Bismol, lead-free solder, and cosmetics. It forms stunning rainbow-coloured hopper crystals when cooled slowly.",fun:"\u{1f4a1} Bismuth grown from the molten metal forms iridescent staircase crystals - among the most beautiful you can make!",risk:"high",riskLabel:"SUPPLY RISK: HIGH"},
Po:{symbol:"Po",name:"Polonium",z:84,color:"#a88080",body:"<strong>Polonium</strong> is intensely radioactive. Has been used in anti-static devices and as a heat source in spacecraft. Discovered by Marie and Pierre Curie, named after Marie's homeland Poland.",fun:"\u{1f4a1} A single gram of polonium-210 generates 140 watts of heat - it glows blue from its own radiation!",risk:"high",riskLabel:"RADIOACTIVE TRACE"},
At:{symbol:"At",name:"Astatine",z:85,color:"#908060",body:"<strong>Astatine</strong> is the rarest naturally occurring element on Earth - less than 30 grams exist at any time, probably far less. Being studied for targeted cancer treatment using At-211.",fun:"\u{1f4a1} Astatine means 'unstable' - its longest-lived isotope has a half-life of just 8.1 hours!",risk:"high",riskLabel:"RADIOACTIVE TRACE"},
Rn:{symbol:"Rn",name:"Radon",z:86,color:"#808090",body:"<strong>Radon</strong> is a radioactive noble gas that seeps from rocks and soil. The second leading cause of lung cancer after smoking. Basements should be tested.",fun:"\u{1f4a1} Radioactive water was once sold as a health tonic - people drank water laced with radon and radium until the dangers became clear!",risk:"medium",riskLabel:"RADIOACTIVE TRACE"},
Fr:{symbol:"Fr",name:"Francium",z:87,color:"#a07060",body:"<strong>Francium</strong> is the most unstable of the first 101 elements. It has no practical uses - barely 30 grams exist in Earth's crust at any moment, constantly created and destroyed by decay.",fun:"\u{1f4a1} Francium is so radioactive that a visible amount would immediately vaporise from its own heat!",risk:"high",riskLabel:"RADIOACTIVE TRACE"},
Ra:{symbol:"Ra",name:"Radium",z:88,color:"#60a878",body:"<strong>Radium</strong> was discovered by Marie and Pierre Curie. Once used in luminous watch dials. Now used in targeted cancer therapy (Ra-223).",fun:"\u{1f4a1} The Curies loved to visit their workroom at night to see their radium samples glowing faintly in the dark - not yet knowing the danger!",risk:"high",riskLabel:"RADIOACTIVE TRACE"},
Ac:{symbol:"Ac",name:"Actinium",z:89,color:"#88a0b8",body:"<strong>Actinium</strong> gives its name to the actinide series. Its isotope Ac-225 is a breakthrough in targeted alpha therapy for cancer treatment.",fun:"\u{1f4a1} Actinium is so radioactive it glows blue in the dark due to the air around it being ionised!",risk:"high",riskLabel:"RADIOACTIVE TRACE"},
Th:{symbol:"Th",name:"Thorium",z:90,color:"#d0b880",body:"<strong>Thorium</strong> is 3\u00d7 more abundant than uranium and could fuel next-generation nuclear reactors. Thorium reactors could produce far less long-lived radioactive waste.",fun:"\u{1f4a1} Named after Thor, the Norse god of thunder - thorium-powered reactors may revolutionise clean energy!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Pa:{symbol:"Pa",name:"Protactinium",z:91,color:"#a0a0a0",body:"<strong>Protactinium</strong> is extremely rare, toxic, and radioactive. It has virtually no commercial uses but is important for understanding nuclear geology.",fun:"\u{1f4a1} In 1961, the UK extracted 125g of protactinium at a cost of $500,000 - one of the priciest elements ever!",risk:"high",riskLabel:"RADIOACTIVE TRACE"},
U:{symbol:"U",name:"Uranium",z:92,color:"#50b850",body:"<strong>Uranium</strong> powers nuclear reactors generating about 9% of the world's electricity. Depleted uranium is used in armour-piercing ammunition due to its extreme density.",fun:"\u{1f4a1} Uranium decays so slowly that half of what the Earth began with is still here, 4.5 billion years on. That makes it only weakly radioactive - but, like lead, it is a poisonous heavy metal.",real:"Uranium miners never touch glowing rock - ore is handled under strict radiation controls.",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Np:{symbol:"Np",name:"Neptunium",z:93,color:"#80a080",body:"<strong>Neptunium</strong> is a by-product of nuclear reactors. Np-237 is used in neutron detection equipment. Named after the planet Neptune, following uranium (Uranus).",fun:"\u{1f4a1} Neptunium was the first synthetic transuranium element - produced in a cyclotron in Berkeley in 1940!",risk:"high",riskLabel:"REACTOR-MADE"},
Pu:{symbol:"Pu",name:"Plutonium",z:94,color:"#e87070",body:"<strong>Plutonium</strong> fuels space probes like Voyager and Curiosity via radioisotope thermoelectric generators. Also used in nuclear weapons and MOX reactor fuel.",fun:"\u{1f4a1} Pu-238 powers the Voyager probes - still running after more than 45 years, with Voyager 1 over 15 billion miles from Earth!",risk:"high",riskLabel:"REACTOR-MADE"},
Be:{symbol:"Be",name:"Beryllium",z:4,color:"#c8e8c8",body:"<strong>Beryllium</strong> is transparent to X-rays, making it ideal for X-ray windows. Incredibly light and stiff, it's used in satellites, missiles, and the James Webb Space Telescope.",fun:"\u{1f4a1} The James Webb Space Telescope's 6.5m mirror is made of gold-coated beryllium segments!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
B:{symbol:"B",name:"Boron",z:5,color:"#d8a090",body:"<strong>Boron</strong> makes borosilicate glass (Pyrex) heat-resistant. Boron fibres are stronger than steel but lighter than aluminium. Essential for plant cell walls.",fun:"\u{1f4a1} Borax from Tibetan lakes was traded along the Silk Road for centuries!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Hg:{symbol:"Hg",name:"Mercury",z:80,color:"#b0b0c0",body:"<strong>Mercury</strong> is the only metal that is liquid at room temperature. Long used in thermometers, fluorescent lamps and dental fillings, but now being phased out. Highly toxic to the nervous system.",fun:"\u{1f4a1} Mercury's chemical symbol Hg is from 'hydrargyrum', from the Greek for 'water-silver'!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
// ─── Synthetic elements (Z=95–118) - display-only, never spawn ───
Am:{symbol:"Am",name:"Americium",z:95,color:"#b49080",body:"<strong>Americium</strong> is used in household smoke detectors - an Am-241 source ionises air to detect smoke particles. It is the artificial element most likely to be in your home.",fun:"\u{1f4a1} Americium in your smoke detector was made in a nuclear reactor - saving lives every day!",risk:"high",riskLabel:"SYNTHETIC"},
Cm:{symbol:"Cm",name:"Curium",z:96,color:"#a0a088",body:"<strong>Curium</strong> provides the alpha particles for X-ray spectrometers on Mars rovers. Named after Marie and Pierre Curie for their pioneering work on radioactivity.",fun:"\u{1f4a1} Cm-244 was the heart of the rock-analysing APXS instruments on the Mars rovers Spirit and Opportunity!",risk:"high",riskLabel:"SYNTHETIC"},
Bk:{symbol:"Bk",name:"Berkelium",z:97,color:"#a09070",body:"<strong>Berkelium</strong> is produced only in milligram amounts in special nuclear reactors. Named after Berkeley, California, where it was first synthesised in 1949.",fun:"\u{1f4a1} Only about one gram of berkelium has ever been made - the 22 mg target used to discover tennessine took 250 days in a reactor!",risk:"high",riskLabel:"SYNTHETIC"},
Cf:{symbol:"Cf",name:"Californium",z:98,color:"#a08870",body:"<strong>Californium</strong> is used in neutron moisture gauges and as a neutron source to start nuclear reactors. Cf-252 can also detect gold and silver ores.",fun:"\u{1f4a1} Californium-252 costs tens of millions of dollars per gram, making it one of the most expensive substances on Earth!",risk:"high",riskLabel:"SYNTHETIC"},
Es:{symbol:"Es",name:"Einsteinium",z:99,color:"#a09878",body:"<strong>Einsteinium</strong> was first identified in the fallout of the 1952 hydrogen bomb test. Named after Albert Einstein. Only tiny amounts have ever been produced.",fun:"\u{1f4a1} Einsteinium was first spotted on filter papers flown through the cloud of the first H-bomb test - a secret kept until 1955!",risk:"high",riskLabel:"SYNTHETIC"},
Fm:{symbol:"Fm",name:"Fermium",z:100,color:"#a09080",body:"<strong>Fermium</strong> was also discovered in H-bomb fallout. Named after Enrico Fermi, creator of the first nuclear reactor. No practical uses outside research.",fun:"\u{1f4a1} Fermium's longest-lived isotope has a half-life of only 100 days - it can never be accumulated in usable amounts!",risk:"high",riskLabel:"SYNTHETIC"},
Md:{symbol:"Md",name:"Mendelevium",z:101,color:"#a09080",body:"<strong>Mendelevium</strong> was the first element produced one atom at a time. Named after Dmitri Mendeleev, who published his periodic table in 1869.",fun:"\u{1f4a1} Only 17 atoms of mendelevium were produced in the original experiment - but that was enough to prove it!",risk:"high",riskLabel:"SYNTHETIC"},
No:{symbol:"No",name:"Nobelium",z:102,color:"#a09080",body:"<strong>Nobelium</strong> is named after Alfred Nobel, inventor of dynamite and founder of the Nobel Prizes. Its discovery was controversially claimed by multiple labs.",fun:"\u{1f4a1} Nobelium prefers the +2 oxidation state, unlike all other actinides - making it a chemical oddity!",risk:"high",riskLabel:"SYNTHETIC"},
Lr:{symbol:"Lr",name:"Lawrencium",z:103,color:"#a09080",body:"<strong>Lawrencium</strong> is the last actinide element. Named after Ernest Lawrence, inventor of the cyclotron. Only a few atoms have ever been produced at once.",fun:"\u{1f4a1} Nobody has ever seen lawrencium - it's been detected only through nuclear decay signatures!",risk:"high",riskLabel:"SYNTHETIC"},
Rf:{symbol:"Rf",name:"Rutherfordium",z:104,color:"#909090",body:"<strong>Rutherfordium</strong> is a superheavy transactinide element. Named after Ernest Rutherford, pioneer of nuclear physics. Even its longest-lived atoms survive only about an hour.",fun:"\u{1f4a1} Rutherfordium was at the centre of a naming battle between American and Soviet scientists during the Cold War!",risk:"high",riskLabel:"SYNTHETIC"},
Db:{symbol:"Db",name:"Dubnium",z:105,color:"#909090",body:"<strong>Dubnium</strong> is named after Dubna, Russia, home of the Joint Institute for Nuclear Research. Its longest-lived isotope has a half-life of about a day.",fun:"\u{1f4a1} Dubnium was simultaneously claimed by labs in Russia and California - the 'Transfermium Wars'!",risk:"high",riskLabel:"SYNTHETIC"},
Sg:{symbol:"Sg",name:"Seaborgium",z:106,color:"#909090",body:"<strong>Seaborgium</strong> is named after Glenn Seaborg, who discovered ten elements. He was the first person to have an element named after them while still alive.",fun:"\u{1f4a1} Glenn Seaborg could write his address as 'Seaborgium, Lawrencium, Berkelium, Californium, Americium'!",risk:"high",riskLabel:"SYNTHETIC"},
Bh:{symbol:"Bh",name:"Bohrium",z:107,color:"#909090",body:"<strong>Bohrium</strong> is named after Niels Bohr, who revolutionised our understanding of atomic structure. Only tiny numbers of atoms have ever been created.",fun:"\u{1f4a1} Bohrium atoms last only seconds to minutes, so they are detected by the particles they give off as they decay!",risk:"high",riskLabel:"SYNTHETIC"},
Hs:{symbol:"Hs",name:"Hassium",z:108,color:"#909090",body:"<strong>Hassium</strong> is named after the German state of Hesse, home to the GSI laboratory where it was first synthesised in 1984.",fun:"\u{1f4a1} Only a tiny number of hassium atoms have ever been made - and most lasted just a few seconds!",risk:"high",riskLabel:"SYNTHETIC"},
Mt:{symbol:"Mt",name:"Meitnerium",z:109,color:"#909090",body:"<strong>Meitnerium</strong> honours Lise Meitner, the physicist who explained nuclear fission but never received the Nobel Prize for it.",fun:"\u{1f4a1} Lise Meitner was nominated for a Nobel Prize nearly 50 times but never won - her element honours her legacy!",risk:"high",riskLabel:"SYNTHETIC"},
Ds:{symbol:"Ds",name:"Darmstadtium",z:110,color:"#909090",body:"<strong>Darmstadtium</strong> is named after Darmstadt, Germany. It was first created by bombarding lead with nickel ions at tremendous energies.",fun:"\u{1f4a1} The first darmstadtium atoms lasted less than a thousandth of a second - heavier kinds made later survive for several seconds!",risk:"high",riskLabel:"SYNTHETIC"},
Rg:{symbol:"Rg",name:"Roentgenium",z:111,color:"#909090",body:"<strong>Roentgenium</strong> honours Wilhelm R\u00f6ntgen, discoverer of X-rays. Predicted to be a noble metal similar to gold. Only a few atoms have ever existed.",fun:"\u{1f4a1} R\u00f6ntgen won the very first Nobel Prize in Physics in 1901 - his discovery changed medicine forever!",risk:"high",riskLabel:"SYNTHETIC"},
Cn:{symbol:"Cn",name:"Copernicium",z:112,color:"#909090",body:"<strong>Copernicium</strong> honours Nicolaus Copernicus, who placed the Sun at the centre of the solar system. Calculations predict a very volatile liquid that behaves more like a noble gas than a metal.",fun:"\u{1f4a1} Early predictions said copernicium might be a gas - newer calculations suggest a liquid that boils at about 67°C!",risk:"high",riskLabel:"SYNTHETIC"},
Nh:{symbol:"Nh",name:"Nihonium",z:113,color:"#909090",body:"<strong>Nihonium</strong> is the first element discovered in Asia. Named after \u2018Nihon\u2019 (Japan), synthesised at RIKEN using a particle accelerator.",fun:"\u{1f4a1} It took the RIKEN team 9 years of firing trillions of zinc ions every second to produce just three atoms of nihonium!",risk:"high",riskLabel:"SYNTHETIC"},
Fl:{symbol:"Fl",name:"Flerovium",z:114,color:"#909090",body:"<strong>Flerovium</strong> honours Georgy Flyorov, who founded the nuclear research lab at Dubna. It sits near the predicted 'island of stability', where superheavy atoms should last longer.",fun:"\u{1f4a1} Flerovium atoms last a couple of seconds instead of milliseconds - an eternity in the superheavy world!",risk:"high",riskLabel:"SYNTHETIC"},
Mc:{symbol:"Mc",name:"Moscovium",z:115,color:"#909090",body:"<strong>Moscovium</strong> is named after Moscow Oblast, home to the Dubna lab. First synthesised in 2003 through a Russian-American collaboration.",fun:"\u{1f4a1} Moscovium decays in under a second - yet in 2024 chemists tested its chemistry using just four atoms!",risk:"high",riskLabel:"SYNTHETIC"},
Lv:{symbol:"Lv",name:"Livermorium",z:116,color:"#909090",body:"<strong>Livermorium</strong> is named after Livermore, California, home of the Lawrence Livermore National Laboratory. A collaborative element between Russia and the US.",fun:"\u{1f4a1} Livermorium was created by smashing calcium ions into curium at a tenth of the speed of light!",risk:"high",riskLabel:"SYNTHETIC"},
Ts:{symbol:"Ts",name:"Tennessine",z:117,color:"#909090",body:"<strong>Tennessine</strong> is named after Tennessee, honouring contributions from Oak Ridge National Laboratory. The heaviest element in the halogens' column - though it may behave more like a metal.",fun:"\u{1f4a1} Making the berkelium target took 250 days in a reactor - then months of calcium bombardment yielded just six atoms!",risk:"high",riskLabel:"SYNTHETIC"},
Og:{symbol:"Og",name:"Oganesson",z:118,color:"#909090",body:"<strong>Oganesson</strong> is the heaviest known element. Named after physicist Yuri Oganessian, one of only two people to have an element named after them while alive.",fun:"\u{1f4a1} Oganesson is predicted to be a solid noble gas - unique among its group, breaking the periodic trend!",risk:"high",riskLabel:"SYNTHETIC"},
As:{symbol:"As",name:"Arsenic",z:33,color:"#a0a070",body:"<strong>Arsenic</strong> is a metalloid used in semiconductors (gallium arsenide), wood preservatives, and alloys. Though toxic, tiny doses of an arsenic compound are used as a life-saving leukaemia medicine.",fun:"\u{1f4a1} The green wallpaper in Napoleon's last home contained arsenic - though it probably was not what killed him!",risk:"medium",riskLabel:"SUPPLY RISK: MEDIUM"},
Pm:{symbol:"Pm",name:"Promethium",z:61,color:"#a0b880",body:"<strong>Promethium</strong> is the only lanthanide with no stable isotopes. Used in nuclear batteries and luminous paint. Virtually all promethium on Earth is artificially produced.",fun:"\u{1f4a1} Named after Prometheus who stole fire from the gods - fitting for an element that glows in the dark!",risk:"high",riskLabel:"REACTOR-MADE"}
};

// ─── Reality checks: how each element is really obtained ───
// Shown on the fact card under the main text. Entries defined inline on an
// element above take precedence; this table covers the rest of Z 1–94.
var REALITY_CHECKS={
H:"Hydrogen is not mined: almost all of it is made from natural gas or coal - only a tiny share by splitting water.",
Be:"Beryllium comes from the minerals bertrandite and beryl - emerald is a green form of beryl.",
B:"Boron is scooped from dried-up desert lake beds as borax-type salts, mostly in Turkey and California.",
C:"Graphite is mined as grey flakes - and much battery graphite is not mined at all but baked from petroleum coke.",
N:"Nitrogen is taken straight from the air, by chilling air until it turns liquid and distilling it.",
O:"Oxygen is distilled from liquefied air - no mine needed, the sky is the ore.",
F:"Fluorine comes from the mineral fluorspar; the pure gas is so aggressive it is mostly made right where it is needed.",
Ne:"Neon is a leftover from liquefying air - it takes about 55,000 litres of air to yield one litre of neon.",
Na:"Sodium metal is never found in nature - it is made by passing electricity through molten salt.",
Mg:"Magnesium is extracted from the rock dolomite, or from seawater and salt-lake brines.",
P:"Phosphorus is mined as phosphate rock - about two-thirds of known reserves lie in Morocco.",
S:"Most sulphur is no longer mined: it is stripped out of oil and natural gas at refineries.",
Cl:"Chlorine is made by running electricity through salt water - the raw material is ordinary salt.",
Ar:"Argon is separated from liquefied air, where it is the third most common gas.",
K:"Potassium is mined as potash - salt beds left behind by ancient evaporated seas.",
Ca:"Calcium is quarried by the mountain as limestone - but the pure metal is rarely made at all.",
Sc:"Scandium has almost no mines of its own; it is recovered in tiny amounts as a byproduct of other ores.",
Ti:"Titanium is common in black beach-sand minerals; turning them into metal takes a slow, costly chemical process.",
V:"Much vanadium is recovered from the slag left over when certain iron ores are made into steel.",
Cr:"Chromium comes from a single ore, chromite - South Africa mines the largest share of it.",
Mn:"Manganese ore comes from open pits and underground mines; most is smelted straight into alloys for steelmaking.",
Ni:"Nickel comes from two very different ores: deep sulphide rock and tropical red laterite soils.",
Zn:"Zinc ore (sphalerite) is roasted and dissolved, then the metal is plated out with electricity.",
Ga:"Gallium has no ore of its own - it is skimmed in traces from the liquor of aluminium refineries.",
Ge:"Germanium is recovered from zinc smelter residues and from the fly ash of certain coals.",
As:"Arsenic is an unwanted guest in copper and gold ores; it is captured from smelter dust.",
Se:"Selenium is collected from the sludge at the bottom of copper refining tanks.",
Br:"Bromine is extracted from very salty brines - the Dead Sea is one of the richest sources.",
Kr:"Krypton is distilled from liquid air, where it makes up just one part in a million.",
Rb:"Rubidium has no ore of its own; small amounts come along with lithium and caesium minerals.",
Sr:"Strontium is mined as the mineral celestine, named for its sky-blue crystals.",
Y:"Yttrium is separated from rare-earth ores, especially clays in southern China and Myanmar.",
Zr:"Zirconium comes from zircon, a heavy mineral sifted out of beach sands in Australia and South Africa.",
Nb:"Nearly all niobium comes from one rock type, carbonatite - and mostly from a single mine in Brazil.",
Mo:"More than half of all molybdenum is a byproduct of big copper mines.",
Tc:"Technetium is not mined: it is made in nuclear reactors, and hospitals draw it fresh from special generators.",
Ru:"Ruthenium is a minor byproduct of platinum mining - a few dozen tonnes a year worldwide.",
Rh:"Rhodium is never mined for itself: it arrives as a trace in platinum and nickel ores.",
Pd:"Palladium is mined together with platinum in South Africa and with nickel in Russia.",
Ag:"Most silver is a byproduct - it comes out of lead, zinc, copper and gold mines.",
Cd:"Cadmium is a byproduct of zinc refining; nobody mines it on purpose.",
Sn:"Tin ore (cassiterite) is so heavy it is often washed out of river gravels, like panning for gold.",
Sb:"Antimony is mined as the mineral stibnite; China, Tajikistan and Russia dominate supply.",
Te:"Tellurium is recovered from the sludge of copper refineries - only about a thousand tonnes a year.",
I:"Iodine is extracted from Chilean nitrate deposits and from brines pumped up with natural gas in Japan.",
Xe:"Xenon is the rarest gas distilled from air: less than one part in ten million.",
Cs:"Caesium comes from the rare mineral pollucite, found in only a handful of deposits worldwide.",
Ba:"Barium is mined as baryte, a mineral so heavy it is used to weigh down oil-well drilling mud.",
La:"Lanthanum is separated from mixed rare-earth ore, where it is one of the most plentiful members.",
Ce:"Cerium is so plentiful in rare-earth ores that producers often have more than they can sell.",
Pr:"Praseodymium and neodymium are so alike that they are often sold unseparated, as 'NdPr'.",
Pm:"Promethium is not mined: there is under a kilogram in the whole of Earth's crust, so it is made in reactors.",
Sm:"Samarium is separated from rare-earth ores by repeating the same chemical step hundreds of times.",
Eu:"Europium is one of the scarcest rare earths - a small fraction of one percent of typical ore.",
Gd:"Gadolinium is separated from rare-earth ores; it is named after the mineral gadolinite.",
Tb:"Terbium comes mostly from clays where rare earths cling loosely and are washed out with a salt solution.",
Dy:"Most dysprosium comes from rare-earth clays in southern China and Myanmar.",
Ho:"Holmium is a minor leftover of heavy rare-earth refining, produced only in small amounts.",
Er:"Erbium is separated from heavy rare-earth concentrates such as xenotime and rare-earth clays.",
Tm:"Thulium is among the least abundant rare earths, so only small amounts are separated each year.",
Yb:"Ytterbium is recovered alongside yttrium from heavy rare-earth ores.",
Lu:"Lutetium is the last and hardest rare earth to separate, which makes it one of the costliest.",
Hf:"Hafnium is obtained only as a leftover when zirconium is purified for nuclear reactors.",
W:"Tungsten is mined as the minerals scheelite and wolframite; China produces about four-fifths of it.",
Re:"Rhenium is captured from the flue dust of molybdenum roasters - themselves a byproduct of copper mines.",
Os:"Osmium is a byproduct of platinum and nickel refining; world output is only about a tonne a year.",
Ir:"Iridium is a byproduct of platinum mining - only about seven tonnes are produced a year.",
Pt:"Platinum ore holds only a few grams per tonne, mined from narrow reefs deep under South Africa.",
Hg:"Mercury is roasted out of the red mineral cinnabar; most mines have closed because it is so toxic.",
Tl:"Thallium is recovered in traces from the dust of zinc and lead smelters.",
Pb:"Lead is mined as galena - but more than half of all lead used today is recycled, mostly from car batteries.",
Bi:"Bismuth is mostly a byproduct of lead and tungsten refining.",
Po:"Polonium is not mined: the tiny amounts used are made by bombarding bismuth in a nuclear reactor.",
At:"Astatine cannot be mined - cyclotrons make it from bismuth, only a few billionths of a gram at a time.",
Rn:"Radon is never mined: it seeps out of rock on its own as uranium and radium decay.",
Fr:"Francium has never been gathered in a weighable amount; it exists only as stray atoms in uranium ore.",
Ra:"Radium was once extracted from tonnes of uranium ore for a single gram; the radium used in medicine today is made with the help of nuclear reactors.",
Ac:"Actinium is far too scarce to mine; medical actinium is made in reactors and accelerators.",
Th:"Thorium piles up as an unwanted byproduct of rare-earth mining from monazite sands.",
Pa:"Protactinium exists only as traces in uranium ore - a few parts per trillion of the crust.",
Np:"Neptunium is made in nuclear reactors; nature holds only fleeting traces in uranium ore.",
Pu:"Plutonium is made in nuclear reactors from uranium; natural traces are almost undetectably small."
};
